use bunkai_rs::segment;

fn with_closing_marks(text: &str, expected: &[usize]) -> Vec<usize> {
    let chars: Vec<char> = text.chars().collect();
    let mut adjusted = expected.to_vec();
    for end in &mut adjusted {
        while *end < chars.len()
            && matches!(
                chars[*end],
                ')' | ']'
                    | '}'
                    | '）'
                    | '］'
                    | '｝'
                    | '〉'
                    | '》'
                    | '」'
                    | '』'
                    | '】'
                    | '〕'
                    | '〗'
                    | '〙'
                    | '〟'
                    | '’'
                    | '”'
                    | '｠'
            )
        {
            *end += 1;
        }
    }
    adjusted.sort_unstable();
    adjusted.dedup();
    adjusted
}

